  { id:'char-l6-m-101-1', type:'mystery', characterId:'micah', category:'Personnages', difficulty: 'hard', answer:'micah', clues:['Prophète — Michée dénonce les injustices et l’infidélité tout en annonçant des promesses concernant le peuple de Dieu.','Dénonce les dirigeants injustes.','Justice'], explanation:'Michée dénonça l’injustice même lorsqu’elle concernait des personnes puissantes.', reference:'Michée 1:1-16' },
  { id:'char-l6-m-101-2', type:'mystery', characterId:'micah', category:'Personnages', difficulty: 'expert', answer:'micah', clues:['Juda, particulièrement les régions rurales et Jérusalem.','Michée annonça fidèlement les messages de Jéhovah et dénonça l’injustice, l’oppression et le faux culte. Il rappela aussi que Jéhovah demande à ses serviteurs d’exercer la justice, d’aimer la fidélité et de marcher modestement avec lui.','Michée annonça qu’un dirigeant sortirait de Bethléhem Éphrata, prophétie que Matthieu appliqua à Jésus.'], explanation:'Il rappela les qualités que Jéhovah attend de ses adorateurs.', reference:'Michée 1:1-16' },
  { id:'char-l6-m-102-1', type:'mystery', characterId:'obadiah', category:'Personnages', difficulty: 'hard', answer:'obadiah', clues:['Prophète — Obadia annonce le jugement contre Édom et évoque le rétablissement du peuple de Jéhovah.','Annonce le jugement contre Édom.','Courage'], explanation:'Jéhovah condamne la joie malveillante devant le malheur d’autrui.', reference:'Abdias 1-21' },
  { id:'char-l6-m-102-2', type:'mystery', characterId:'obadiah', category:'Personnages', difficulty: 'expert', answer:'obadiah', clues:['Juda; le contexte de la prophétie concerne particulièrement Édom et Jérusalem.','Obadia transmit le jugement de Jéhovah contre Édom pour son attitude envers Juda. Son message souligne que Jéhovah voit les actes commis contre son peuple et demande des comptes.','Le livre d’Obadia est le plus court des livres prophétiques des Écritures hébraïques, avec un seul chapitre.'], explanation:'Abdias montre que la violence et l’orgueil nationaux ne restent pas impunis.', reference:'Abdias 1-21' },
  { id:'char-l6-m-103-1', type:'mystery', characterId:'joel', category:'Personnages', difficulty: 'hard', answer:'joel', clues:['Prophète — Yoël utilise une invasion de sauterelles comme contexte pour appeler le peuple à revenir à Jéhovah.','Décrit une invasion dévastatrice.','Urgence'], explanation:'Joël invita le peuple à revenir vers Jéhovah avec tout son cœur.', reference:'Joël 1:1-20' },
  { id:'char-l6-m-103-2', type:'mystery', characterId:'joel', category:'Personnages', difficulty: 'expert', answer:'joel', clues:['Juda et Jérusalem.','Joël appela le peuple à revenir à Jéhovah de tout son cœur et annonça une restauration après le jugement. Son message met l’accent sur la miséricorde et la compassion de Jéhovah.','Pierre cita la prophétie de Joël concernant l’effusion de l’esprit saint le jour de la Pentecôte.'], explanation:'Il montra que la repentance véritable ne consiste pas seulement en gestes extérieurs.', reference:'Joël 1:1-20' },
  { id:'char-l6-m-104-1', type:'mystery', characterId:'nahum', category:'Personnages', difficulty: 'hard', answer:'nahum', clues:['Prophète — Nahum annonce la chute de Ninive et présente Jéhovah comme un Dieu juste qui ne laisse pas le mal impuni.','Annonce la chute de Ninive.','Courage'], explanation:'Nahum rappelle que Jéhovah ne laisse pas indéfiniment l’oppression impunie.', reference:'Nahum 1:1-15' },
  { id:'char-l6-m-104-2', type:'mystery', characterId:'nahum', category:'Personnages', difficulty: 'expert', answer:'nahum', clues:['Juda et Ninive, en Assyrie.','Nahoum annonça le jugement de Jéhovah contre Ninive et montra en même temps que Jéhovah est un refuge pour ceux qui se confient en lui.','La prophétie de Nahoum décrit la chute de Ninive, capitale de l’Assyrie, puissance qui avait opprimé de nombreux peuples.'], explanation:'Son message devait consoler ceux qui avaient souffert sous la domination assyrienne.', reference:'Nahum 1:1-15' },
  { id:'char-l6-m-105-1', type:'mystery', characterId:'zechariah_priest', category:'Personnages', difficulty: 'hard', answer:'zechariah_priest', clues:['Zacharie était un prêtre de la classe d’Abiya, mari d’Élisabeth et père de Jean le Baptiste. L’ange Gabriel lui annonça la naissance de son fils.','Il sert comme prêtre au temple de Jérusalem.','Piété'], explanation:'Zacharie servait fidèlement au temple lorsqu’il reçut son annonce.', reference:'Luc 1:5-25' },
  { id:'char-l6-m-105-2', type:'mystery', characterId:'zechariah_priest', category:'Personnages', difficulty: 'expert', answer:'zechariah_priest', clues:['Juda, notamment le temple de Jérusalem et la région montagneuse où vivait sa famille.','Zekaria, père de Jean le Baptiseur, servait comme prêtre et reçut une annonce angélique concernant la naissance de son fils. Après avoir douté du message, il retrouva la parole et loua Jéhovah.','Zekaria resta muet depuis le moment où Gabriel lui annonça la naissance de Jean jusqu’à la circoncision de l’enfant, lorsqu’il écrivit son nom sur une tablette.'], explanation:'Il eut momentanément du mal à croire une promesse qui semblait humainement impossible.', reference:'Luc 1:5-25' },
  { id:'char-l6-m-106-1', type:'mystery', characterId:'elizabeth', category:'Personnages', difficulty: 'hard', answer:'elizabeth', clues:['Élisabeth était une descendante d’Aaron, épouse du prêtre Zekaria et mère de Jean le Baptiseur. Elle était parente de Marie.','Elle et Zekaria sont décrits comme justes devant Dieu.','Foi'], explanation:'Élisabeth et Zacharie étaient décrits comme justes devant Dieu malgré leur stérilité.', reference:'Luc 1:5-25' },
  { id:'char-l6-m-106-2', type:'mystery', characterId:'elizabeth', category:'Personnages', difficulty: 'expert', answer:'elizabeth', clues:['La région montagneuse de Juda.','Élisabeth était décrite comme juste devant Dieu et observait fidèlement ses commandements. Elle reconnut sous l’influence de l’esprit saint le rôle particulier de Marie et de l’enfant qu’elle portait.','Élisabeth était une parente de Marie et était déjà âgée lorsqu’elle conçut Jean le Baptiseur.'], explanation:'Elle accueillit Marie avec chaleur et discernement spirituel.', reference:'Luc 1:5-25' },
  { id:'char-l6-m-107-1', type:'mystery', characterId:'joseph_jesus_father', category:'Personnages', difficulty: 'hard', answer:'joseph_jesus_father', clues:['Joseph était le mari de Marie et le père adoptif de Jésus. Il était charpentier et descendait de David.','Il accepte de prendre Marie pour femme malgré sa grossesse miraculeuse.','Obéissance'], explanation:'Joseph accepta la situation inhabituelle concernant la grossesse de Marie après avoir reçu une explication divine.', reference:'Matthieu 1:18-25' },
  { id:'char-l6-m-107-2', type:'mystery', characterId:'joseph_jesus_father', category:'Personnages', difficulty: 'expert', answer:'joseph_jesus_father', clues:['Bethléem, Égypte et Nazareth.','Joseph était un homme juste qui obéit aux instructions reçues de Jéhovah par l’intermédiaire des anges. Il protégea Jésus en acceptant de prendre Marie comme femme et en emmenant la famille en Égypte.','Joseph exerçait le métier de charpentier et apprit ce métier à Jésus, qui fut lui-même appelé « le charpentier ».'], explanation:'Il protégea Jésus en obéissant rapidement aux avertissements reçus.', reference:'Matthieu 1:18-25' },
  { id:'char-l6-m-108-1', type:'mystery', characterId:'joseph_caiaphas', category:'Personnages', difficulty: 'hard', answer:'joseph_caiaphas', clues:['Joseph Caïphe était le grand prêtre juif qui participa aux démarches contre Jésus et qui présida des interrogatoires liés à ses disciples.','Il participe au complot visant Jésus.','Autorité religieuse'], explanation:'Caïphe occupait une position religieuse très importante.', reference:'Matthieu 26:57-68' },
  { id:'char-l6-m-108-2', type:'mystery', characterId:'joseph_caiaphas', category:'Personnages', difficulty: 'expert', answer:'joseph_caiaphas', clues:['Jérusalem.','Caïphe occupait la fonction de grand prêtre au moment du procès de Jésus. La Bible rapporte ses décisions et ses paroles, mais ne le présente pas comme un adorateur fidèle de Jéhovah.','Caïphe prophétisa, sans comprendre pleinement la portée de ses paroles, qu’il était avantageux qu’un seul homme meure pour le peuple.'], explanation:'Il participa au complot visant à faire mourir Jésus.', reference:'Matthieu 26:57-68' },
  { id:'char-l6-m-109-1', type:'mystery', characterId:'joanna', category:'Personnages', difficulty: 'hard', answer:'joanna', clues:['Jeanne était une femme qui avait été guérie par Jésus et qui le soutenait, avec d’autres femmes, au moyen de ses biens.','Elle avait été guérie par Jésus.','Générosité'], explanation:'Jeanne avait personnellement bénéficié de l’aide de Jésus.', reference:'Luc 8:1-3' },
  { id:'char-l6-m-109-2', type:'mystery', characterId:'joanna', category:'Personnages', difficulty: 'expert', answer:'joanna', clues:['Galilée et Jérusalem.','Jeanne comptait parmi les femmes qui avaient été guéries par Jésus et qui le soutenaient avec leurs ressources. Elle faisait partie de celles qui annoncèrent aux apôtres que le tombeau était vide.','Jeanne était la femme de Chuza, intendant d’Hérode, et faisait partie des femmes qui accompagnèrent Jésus et ses apôtres.'], explanation:'Elle soutenait Jésus et les Douze avec ses ressources.', reference:'Luc 8:1-3' },
  { id:'char-l6-m-110-1', type:'mystery', characterId:'samaritan_leper', category:'Personnages', difficulty: 'hard', answer:'samaritan_leper', clues:['L’un des dix lépreux guéris par Jésus était un Samaritain. Il fut le seul des dix à revenir remercier Jésus et à glorifier Dieu.','Dix lépreux demandent à Jésus d’avoir pitié d’eux.','Gratitude'], explanation:'Il cria vers Jésus avec foi pour demander miséricorde.', reference:'Luc 17:11-19' },
  { id:'char-l6-m-110-2', type:'mystery', characterId:'samaritan_leper', category:'Personnages', difficulty: 'expert', answer:'samaritan_leper', clues:['Entre la Samarie et la Galilée.','Le Samaritain guéri de la lèpre revint vers Jésus, glorifia Dieu et le remercia. Jésus souligna sa foi, alors que les autres guéris n’étaient pas revenus pour rendre gloire à Dieu.','Il était le seul des dix lépreux guéris à revenir remercier Jésus, et il était Samaritain.'], explanation:'Il obéit à l’instruction de Jésus d’aller se montrer aux prêtres.', reference:'Luc 17:11-19' },
  { id:'char-l6-m-111-1', type:'mystery', characterId:'woman_issue_blood', category:'Personnages', difficulty: 'hard', answer:'woman_issue_blood', clues:['La femme qui avait des pertes de sang souffrait depuis 12 ans. Elle s’approcha discrètement de Jésus avec la conviction que même toucher son vêtement pourrait la guérir.','Elle souffre depuis 12 ans et a dépensé ses ressources auprès de nombreux médecins.','Foi'], explanation:'Elle endura une maladie longue et épuisante.', reference:'Marc 5:25-34' },
  { id:'char-l6-m-111-2', type:'mystery', characterId:'woman_issue_blood', category:'Personnages', difficulty: 'expert', answer:'woman_issue_blood', clues:['Galilée, dans la région de Capharnaüm.','La femme qui souffrait d’une perte de sang depuis douze ans manifesta une grande foi en Jésus. Elle pensait qu’il lui suffirait de toucher son vêtement pour être guérie.','Elle dépensait tout ce qu’elle avait pour des médecins sans être guérie avant de s’approcher de Jésus.'], explanation:'Elle fit confiance au pouvoir de Jésus malgré sa situation.', reference:'Marc 5:25-34' },
  { id:'char-l6-m-112-1', type:'mystery', characterId:'gerasene_man', category:'Personnages', difficulty: 'hard', answer:'gerasene_man', clues:['L’homme de la région des Géraséniens que Jésus délivra était sous l’influence de nombreux démons. Après sa délivrance, il voulut accompagner Jésus, mais Jésus lui confia une autre mission.','Il vivait dans les tombeaux et ne pouvait être maîtrisé.','Reconnaissance'], explanation:'Il souffrait profondément à cause de l’influence démoniaque.', reference:'Marc 5:1-20' },
  { id:'char-l6-m-112-2', type:'mystery', characterId:'gerasene_man', category:'Personnages', difficulty: 'expert', answer:'gerasene_man', clues:['Région des Géraséniens, à l’est de la mer de Galilée.','L’homme possédé de la région des Géraséniens fut libéré par Jésus d’une situation profondément éprouvante. Il voulut ensuite accompagner Jésus, mais Jésus lui demanda de retourner chez lui et de raconter ce que Dieu avait fait pour lui.','Après sa guérison, l’homme annonça dans toute la ville ce que Jésus avait fait pour lui.'], explanation:'Jésus le libéra complètement de cette oppression.', reference:'Marc 5:1-20' },
  { id:'char-l6-m-113-1', type:'mystery', characterId:'jason_thessalonica', category:'Personnages', difficulty: 'hard', answer:'jason_thessalonica', clues:['Jason était un chrétien de Thessalonique qui accueillit Paul et Silas chez lui. Une foule hostile l’entraîna ensuite devant les autorités.','Il accueille Paul et Silas chez lui.','Hospitalité'], explanation:'Jason ouvrit sa maison à Paul et Silas.', reference:'Actes 17:1-9' },
  { id:'char-l6-m-113-2', type:'mystery', characterId:'jason_thessalonica', category:'Personnages', difficulty: 'expert', answer:'jason_thessalonica', clues:['Thessalonique, en Macédoine.','Jason accueillit Paul et Silas à Thessalonique et fut ensuite entraîné dans l’opposition suscitée par la prédication. Il fournit une caution aux autorités pour éviter de nouveaux troubles.','Une foule hostile accusa Paul et Silas d’agir contre les décrets de César et prétendit qu’ils disaient qu’un autre roi, Jésus, existait.'], explanation:'Il fut entraîné dans un conflit public à cause de son soutien aux missionnaires.', reference:'Actes 17:1-9' },
  { id:'char-l6-m-114-1', type:'mystery', characterId:'onesiphorus', category:'Personnages', difficulty: 'hard', answer:'onesiphorus', clues:['Onésiphore était un chrétien qui apporta un soutien précieux à Paul, notamment pendant ses difficultés à Rome.','Il encourage souvent Paul.','Courage'], explanation:'Onésiphore n’eut pas honte de Paul malgré son emprisonnement.', reference:'2 Timothée 1:15-18' },
  { id:'char-l6-m-114-2', type:'mystery', characterId:'onesiphorus', category:'Personnages', difficulty: 'expert', answer:'onesiphorus', clues:['Éphèse et Rome.','Onésiphore rechercha Paul et le réconforta, même pendant la captivité de l’apôtre. Paul pria pour que la miséricorde de Jéhovah soit accordée à sa maisonnée.','Paul se souvenait qu’Onésiphore n’avait pas eu honte de ses chaînes et qu’il l’avait recherché avec empressement à Rome.'], explanation:'Il fit des efforts pour retrouver Paul à Rome.', reference:'2 Timothée 1:15-18' },
  { id:'char-l6-m-115-1', type:'mystery', characterId:'mary_mother_james', category:'Personnages', difficulty: 'hard', answer:'mary_mother_james', clues:['Marie, mère de Jacques, était une chrétienne de Jérusalem dont la maison servit de lieu de rassemblement pour les disciples.','Elle accompagne Jésus et le sert avec d’autres femmes pendant son ministère.','Hospitalité'], explanation:'Marie servit Jésus pendant son ministère avec d’autres femmes.', reference:'Matthieu 27:55-61' },
  { id:'char-l6-m-115-2', type:'mystery', characterId:'mary_mother_james', category:'Personnages', difficulty: 'expert', answer:'mary_mother_james', clues:['Galilée et Jérusalem.','Marie mère de Jacques comptait parmi les femmes qui suivirent Jésus et le soutinrent. Elle fut aussi présente après sa mort et participa aux événements liés à sa résurrection.','Marie mère de Jacques figurait parmi les femmes qui vinrent au tombeau avec des aromates et découvrirent qu’il était ouvert.'], explanation:'Elle resta présente au moment de sa mort, malgré les circonstances difficiles.', reference:'Matthieu 27:55-61' },
  { id:'char-l6-m-116-1', type:'mystery', characterId:'mary_mark_mother', category:'Personnages', difficulty: 'hard', answer:'mary_mark_mother', clues:['Marie, mère de Jean-Marc, était une chrétienne de Jérusalem dont la maison accueillait des disciples. Son fils Jean-Marc devint compagnon de mission.','Les chrétiens se réunissent chez elle pour prier pendant l’emprisonnement de Pierre.','Hospitalité'], explanation:'Marie mettait sa maison à disposition pour les réunions chrétiennes.', reference:'Actes 12:5-17' },
  { id:'char-l6-m-116-2', type:'mystery', characterId:'mary_mark_mother', category:'Personnages', difficulty: 'expert', answer:'mary_mark_mother', clues:['Jérusalem.','Marie, mère de Jean-Marc, était une chrétienne dont la maison servait de lieu de réunion pour les disciples à Jérusalem. Les croyants s’y réunirent notamment pendant que Pierre était emprisonné.','Lorsque Pierre fut libéré miraculeusement, il se rendit à la maison de Marie, où de nombreux disciples étaient réunis et priaient.'], explanation:'Elle soutenait une congrégation qui priait activement.', reference:'Actes 12:5-17' },
  { id:'char-l6-m-117-1', type:'mystery', characterId:'apphia', category:'Personnages', difficulty: 'hard', answer:'apphia', clues:['Apphia était une chrétienne associée à Philémon et à l’assemblée qui se réunissait chez lui. Paul lui adresse personnellement ses salutations.','Paul l’inclut parmi les destinataires de sa lettre à Philémon.','Engagement chrétien'], explanation:'Apphia était connue de Paul et associée à la congrégation de Colosses.', reference:'Philémon 1-2' },
  { id:'char-l6-m-117-2', type:'mystery', characterId:'apphia', category:'Personnages', difficulty: 'expert', answer:'apphia', clues:['Colosses, en Asie Mineure.','Apphia était une chrétienne associée à Philémon et à Archippe. Paul lui adressa personnellement sa lettre, ce qui indique qu’elle faisait partie des personnes concernées par la situation d’Onésime.','Apphia est saluée avec Philémon et Archippe au début de la lettre à Philémon. Le texte la présente comme une personne directement concernée par la vie de la congrégation et par la situation d’Onésime.'], explanation:'Elle reçut une lettre qui traitait d’une question chrétienne délicate concernant Onésime.', reference:'Philémon 1-2' },
  { id:'char-l6-m-118-1', type:'mystery', characterId:'archippus', category:'Personnages', difficulty: 'hard', answer:'archippus', clues:['Archippe était un chrétien associé à Philémon et Apphia et à l’assemblée qui se réunissait chez eux. Paul l’encourage à accomplir pleinement son ministère.','Paul le salue dans la lettre à Philémon.','Engagement'], explanation:'Archippe avait reçu un ministère dans le Seigneur.', reference:'Philémon 1-2' },
  { id:'char-l6-m-118-2', type:'mystery', characterId:'archippus', category:'Personnages', difficulty: 'expert', answer:'archippus', clues:['Colosses, en Asie Mineure.','Archippe avait reçu un ministère dans le Seigneur et Paul l’encouragea à veiller à bien l’accomplir. Il était associé à Philémon et Apphia et à la congrégation qui se réunissait chez eux.','Paul demanda aux Colossiens de dire à Archippe de continuer à veiller à bien accomplir le ministère qu’il avait reçu dans le Seigneur.'], explanation:'Paul le connaissait suffisamment pour lui adresser une exhortation personnelle.', reference:'Philémon 1-2' },
  { id:'char-l6-m-119-1', type:'mystery', characterId:'john_mark', category:'Personnages', difficulty: 'hard', answer:'john_mark', clues:['Jean-Marc était un chrétien de Jérusalem qui accompagna Paul et Barnabas dans une partie de leur première tournée missionnaire. Après une séparation, il retrouva la confiance de Paul.','Il accompagne Paul et Barnabas depuis Jérusalem.','Esprit de service'], explanation:'Jean-Marc commença son service missionnaire avec Paul et Barnabas.', reference:'Actes 12:12,25' },
  { id:'char-l6-m-119-2', type:'mystery', characterId:'john_mark', category:'Personnages', difficulty: 'expert', answer:'john_mark', clues:['Jérusalem, Antioche et diverses régions missionnaires.','Jean-Marc progressa dans le service chrétien. Après avoir quitté Paul et Barnabas pendant leur premier voyage missionnaire, il retrouva la confiance de Paul et devint finalement un collaborateur utile.','À la fin de sa vie, Paul demanda à Timothée de faire venir Marc, car il lui était utile pour le ministère.'], explanation:'Il abandonna le voyage à un moment donné, ce qui provoqua plus tard un désaccord entre Paul et Barnabas.', reference:'Actes 12:12,25' },
  { id:'char-l6-m-120-1', type:'mystery', characterId:'priscilla', category:'Personnages', difficulty: 'hard', answer:'priscilla', clues:['Priscille, avec son mari Aquila, était une chrétienne qui collabora étroitement avec Paul. Elle contribua à expliquer plus exactement la voie de Dieu à Apollos.','Elle et Aquila travaillent avec Paul à Corinthe.','Hospitalité'], explanation:'Priscille travaillait avec Aquilas pour subvenir à leurs besoins.', reference:'Actes 18:18-28' },
  { id:'char-l6-m-120-2', type:'mystery', characterId:'priscilla', category:'Personnages', difficulty: 'expert', answer:'priscilla', clues:['Corinthe, Éphèse et Rome.','Priscille servait Jéhovah avec Aquilas en combinant travail, prédication, enseignement et hospitalité. Avec son mari, elle expliqua plus exactement la voie de Dieu à Apollos.','Paul appelle Priscille et Aquilas ses collaborateurs en Christ Jésus et dit qu’ils avaient risqué leur vie pour lui.'], explanation:'Elle participa activement à l’enseignement chrétien avec son mari.', reference:'Actes 18:18-28' },
  { id:'char-l6-m-121-1', type:'mystery', characterId:'claudius_lycias', category:'Personnages', difficulty: 'hard', answer:'claudius_lycias', clues:['Claude Lysias était le commandant militaire romain de Jérusalem qui fit protéger Paul lorsqu’une foule voulut le tuer.','Il intervient pour empêcher que Paul soit tué par la foule.','Réaction rapide'], explanation:'Il intervint rapidement lorsqu’une foule attaqua Paul.', reference:'Actes 21:31-40' },
  { id:'char-l6-m-121-2', type:'mystery', characterId:'claudius_lycias', category:'Personnages', difficulty: 'expert', answer:'claudius_lycias', clues:['Jérusalem et Césarée.','Le récit ne présente pas Claude Lysias comme adorateur de Jéhovah. Cependant, ses décisions administratives protégèrent Paul et permirent à l’apôtre de continuer à rendre témoignage.','Claude Lysias apprit que Paul était citoyen romain et prit alors des précautions particulières avant de le faire interroger et transférer.'], explanation:'Il vérifia le statut de Paul avant de le faire fouetter.', reference:'Actes 21:31-40' },
  { id:'char-l6-m-122-1', type:'mystery', characterId:'julius_centurion', category:'Personnages', difficulty: 'hard', answer:'julius_centurion', clues:['Julius était un centurion de la cohorte d’Auguste chargé de conduire Paul et d’autres prisonniers vers Rome.','Il reçoit la responsabilité de conduire Paul vers Rome.','Humanité'], explanation:'Julius permit à Paul de recevoir l’aide de ses amis à Sidon.', reference:'Actes 27:1-44' },
  { id:'char-l6-m-122-2', type:'mystery', characterId:'julius_centurion', category:'Personnages', difficulty: 'expert', answer:'julius_centurion', clues:['Césarée, Méditerranée, Malte et Rome.','Julius n’est pas présenté comme adorateur de Jéhovah. Il traita néanmoins Paul avec considération pendant le voyage vers Rome et contribua à préserver la vie des prisonniers après le naufrage.','Julius permit à Paul de rendre visite à des amis à Sidon avant de poursuivre le voyage vers Rome.'], explanation:'Il écouta Paul au cours de la traversée.', reference:'Actes 27:1-44' },
  { id:'char-l6-m-123-1', type:'mystery', characterId:'gaius_macedonian', category:'Personnages', difficulty: 'hard', answer:'gaius_macedonian', clues:['Gaïus le Macédonien était un compagnon de Paul associé à Aristarque lors de l’émeute d’Éphèse.','Il accompagne Paul dans son activité missionnaire.','Fidélité'], explanation:'Gaius accompagna Paul dans son activité missionnaire.', reference:'Actes 19:28-31' },
  { id:'char-l6-m-123-2', type:'mystery', characterId:'gaius_macedonian', category:'Personnages', difficulty: 'expert', answer:'gaius_macedonian', clues:['Macédoine et Éphèse.','Gaïus le Macédonien était un compagnon de Paul impliqué dans le service chrétien. Il fut exposé au danger lors de l’émeute d’Éphèse.','Gaïus et Aristarque furent saisis par la foule pendant l’émeute d’Éphèse, alors que les artisans s’opposaient à la prédication de Paul.'], explanation:'Il accepta les risques liés à la prédication chrétienne.', reference:'Actes 19:28-31' },
  { id:'char-l6-m-124-1', type:'mystery', characterId:'aristarchus', category:'Personnages', difficulty: 'hard', answer:'aristarchus', clues:['Aristarque était un Macédonien de Thessalonique et un compagnon de voyage de Paul. Il partagea même une période de captivité avec lui.','Il accompagne Paul depuis la Macédoine.','Fidélité'], explanation:'Aristarque resta proche de Paul malgré l’opposition.', reference:'Actes 19:29-31' },
  { id:'char-l6-m-124-2', type:'mystery', characterId:'aristarchus', category:'Personnages', difficulty: 'expert', answer:'aristarchus', clues:['Thessalonique, Éphèse et Rome.','Aristarque resta un compagnon fidèle de Paul et partagea avec lui des situations dangereuses, jusqu’au voyage vers Rome et à une période de captivité.','Paul appelle Aristarque son « compagnon de captivité » dans sa lettre aux Colossiens.'], explanation:'Il fut exposé au danger pendant l’émeute d’Éphèse.', reference:'Actes 19:29-31' },
  { id:'char-l6-m-125-1', type:'mystery', characterId:'syntyche', category:'Personnages', difficulty: 'hard', answer:'syntyche', clues:['Syntyche était une chrétienne de Philippes qui avait travaillé avec Paul pour la bonne nouvelle. Paul lui adresse le même appel à l’unité qu’à Évodie.','Elle a collaboré avec Paul dans la proclamation de la bonne nouvelle.','Zèle'], explanation:'Syntyche participa activement à la prédication avec Paul.', reference:'Philippiens 4:2-3' },
  { id:'char-l6-m-125-2', type:'mystery', characterId:'syntyche', category:'Personnages', difficulty: 'expert', answer:'syntyche', clues:['Philippes, en Macédoine.','Syntyche avait travaillé avec Paul pour la bonne nouvelle et faisait partie de la congrégation de Philippes. Paul l’encouragea, avec Évodie, à retrouver la même pensée dans le Seigneur.','Paul demanda à un collaborateur fidèle d’aider Évodie et Syntyche à résoudre leur désaccord.'], explanation:'Elle avait une place suffisamment connue dans la congrégation pour être citée personnellement.', reference:'Philippiens 4:2-3' }
